const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: 'x²' },
      { kind: 'text', payload: '−' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '+' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '=' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'a = 1' },
      { kind: 'text', payload: 'b = −4' },
      { kind: 'text', payload: 'c = 4' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 0' },
      { kind: 'text', payload: 'Δ = 0' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W / 2;
    var yEq = H * 0.24;
    var yCall = H * 0.50;
    var yDisc = H * 0.73;
    var yDelta = H * 0.86;
    var left = Math.max(20, cx - 138);
    var xs = [left, left + 30, left + 76, left + 106, left + 140, left + 178, left + 206, left + 244, left + 276];
    var colors = {
      a: '#c0392b',
      b: '#1f5fbf',
      c: '#1e8f5a',
      dark: '#1f2937',
      white: '#ffffff',
      greenBg: '#e8f7ef'
    };
    var paths = [];
    var children = [];
    function addPath(id, commands, fill, strokeColor, strokeWidth) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (fill) { node.fill = fill; }
      if (strokeColor) { node.stroke = { width: strokeWidth || 2, color: strokeColor }; }
      children.push(node);
    }
    addPath('panel', visualSdk.polyline([[0, 0], [W, 0], [W, H], [0, H], [0, 0]]), colors.white, null, 0);
    var tokenTexts = ['c0', 'c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8'];
    var tokenColors = [colors.a, colors.dark, colors.b, colors.b, colors.dark, colors.c, colors.c, colors.dark, colors.dark];
    for (var i = 0; i < tokenTexts.length; i++) {
      children.push({
        type: 'label',
        contentId: tokenTexts[i],
        anchor: { x: xs[i], y: yEq },
        hAlign: 'center',
        vAlign: 'middle',
        color: tokenColors[i]
      });
    }
    var callouts = [
      { x: xs[0], label: 'c9', color: colors.a, targetX: xs[0] },
      { x: (xs[2] + xs[3]) / 2, label: 'c10', color: colors.b, targetX: xs[3] },
      { x: xs[6], label: 'c11', color: colors.c, targetX: xs[6] }
    ];
    for (var j = 0; j < callouts.length; j++) {
      var co = callouts[j];
      addPath('lead' + j, visualSdk.polyline([[co.x, yCall - 10], [co.targetX, yEq + 20]]), null, co.color, 2);
      addPath('dot' + j, visualSdk.circle(co.targetX, yEq + 20, 3), co.color, co.color, 1);
      children.push({
        type: 'label',
        contentId: co.label,
        anchor: { x: co.x, y: yCall },
        hAlign: 'center',
        vAlign: 'top',
        color: co.color
      });
    }
    var discW = Math.min(W - 80, 360);
    addPath('discRule', visualSdk.polyline([[cx - discW / 2, yDisc + 22], [cx + discW / 2, yDisc + 22]]), null, colors.dark, 3);
    children.push({
      type: 'label',
      contentId: 'c12',
      anchor: { x: cx, y: yDisc },
      hAlign: 'center',
      vAlign: 'middle',
      color: colors.dark
    });
    var dw = 100;
    addPath('deltaPill', visualSdk.polyline([[cx - dw / 2, yDelta - 18], [cx + dw / 2, yDelta - 18], [cx + dw / 2, yDelta + 18], [cx - dw / 2, yDelta + 18], [cx - dw / 2, yDelta - 18]]), colors.greenBg, colors.c, 2);
    children.push({
      type: 'label',
      contentId: 'c13',
      anchor: { x: cx, y: yDelta },
      hAlign: 'center',
      vAlign: 'middle',
      color: colors.c
    });
    return {
      schemaVersion: 1,
      sceneId: 'quadratic-root-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
